gZe(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u0631\u0627\u062d\u0644 \u0625\u0646\u062a\u0627\u062c \u0644\u0625\u0639\u062f\u0627\u062f\u0647\u0627 \u0628\u0639\u062f."},
gZs(){return"\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u0648\u0649"},
