ga2z(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u06cc\u0627\u0633\u0627\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
ga2q(){return"\u06cc\u0627\u0633\u0627\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
ga2r(){return"\u067e\u0632\u06cc\u0634\u06a9"},
ga2y(){return"\u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
gGO(){return"\u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646"},
ga2u(){return"\u0646\u0631\u062e (\u0628\u0695 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9\u060c \u06cc\u0627\u0646 %)"},
ga2t(){return"\u0628\u06ce \u0633\u0646\u0648\u0648\u0631 \u0628\u06c6 \u0698\u0645\u0627\u0631\u06d5\u06cc \u06cc\u06d5\u06a9\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633"},
ga2o(){return"\u0628\u0695\u06cc \u0632\u06cc\u0627\u062f\u06d5 \u0628\u06c6 \u0647\u06d5\u0631 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9 (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
