gPb(){return"\u0644\u06ce\u06af\u06d5\u0631\u06cc\u0627\u0646 \u0644 \u06a9\u0627\u0644\u0627\u06cc\u0627\u0646"},
gP0(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646 \u0648\u06d5\u06a9 \u06a9\u0627\u0644\u0627\u06cc\u06d5\u06a9\u0627 \u0646\u0648\u06cc"},
gOY(){return"\u0633\u06d5\u0631 \u0628 \u0645\u0627\u062f\u062f\u06ce \u06a4\u06d5"},
